-- Importazione catalogo incantesimi 2024
-- Generato da incantesimi_5e_spellbook_580_dettagli_it_metri.json. Record: 444.
-- Prerequisiti: admin_shared_catalog_rls.sql e extend_shared_spells_spellbook_import.sql.
-- scrapeStatus e verifiedEditions/verifiedVersion sono intenzionalmente ignorati.

begin;

do $spellbook_import$
declare
  v_created_by uuid;
begin
  select user_id into v_created_by
  from public.catalog_admins
  order by created_at, user_id
  limit 1;

  if v_created_by is null then
    raise exception 'Nessun amministratore presente in public.catalog_admins.';
  end if;

  create temporary table spellbook_import_rows on commit drop as
    select source_key, rules_version, name, level, school, caster_classes, cast_time, range, duration, components, material, concentration, ritual, attack_roll, saving_throw_ability, attack_range_type, damage_die, damage_modifier, damage_type, upcast_damage_die, upcast_damage_modifier, upcast_start_level, upcast_description, description, source, source_url
    from public.shared_spells
    with no data;

  insert into spellbook_import_rows (
    source_key,
    rules_version,
    name,
    level,
    school,
    caster_classes,
    cast_time,
    range,
    duration,
    components,
    material,
    concentration,
    ritual,
    attack_roll,
    saving_throw_ability,
    attack_range_type,
    damage_die,
    damage_modifier,
    damage_type,
    upcast_damage_die,
    upcast_damage_modifier,
    upcast_start_level,
    upcast_description,
    description,
    source,
    source_url
  )
  values
    ('acid-splash', '2024', 'Spruzzo di acido', 0, 'invocazione', array['artefice', 'stregone', 'mago']::text[], 'Azione', '18 metri', 'Istantanea', 'V, S', null, false, false, false, 'dex', null, '1d6', null, 'acido', null, null, null, 'Potenziamento del trucchetto. Il danno aumenta di 1d6 quando raggiungi i livelli 5 (2d6), 11 (3d6) e 17 (4d6).', 'Crei una bolla acida in un punto entro il raggio d''azione, dove esplode in una sfera del raggio di 1,5 metri. Ogni creatura all''interno di quella sfera deve superare un tiro salvezza di Destrezza o subire 1d6 danni da acido.

Potenziamento del trucchetto. Il danno aumenta di 1d6 quando raggiungi i livelli 5 (2d6), 11 (3d6) e 17 (4d6).', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/acid-splash'),
    ('aid', '2024', 'Aiuto', 2, 'abiurazione', array['artefice', 'bardo', 'chierico', 'druido', 'paladino', 'ranger']::text[], 'Azione', '9 metri', '8 ore', 'V, S, M', 'una striscia di stoffa bianca', false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. I Punti Ferita di ciascun bersaglio aumentano di 5 per ogni livello dello slot incantesimo superiore a 2.', 'Scegli fino a tre creature entro il raggio d''azione. Il massimo dei Punti Ferita e i Punti Ferita attuali di ciascun bersaglio aumentano di 5 per tutta la durata dell''effetto.

Utilizzo di uno slot incantesimo di livello superiore. I Punti Ferita di ciascun bersaglio aumentano di 5 per ogni livello dello slot incantesimo superiore a 2.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/aid'),
    ('alarm', '2024', 'Allarme', 1, 'abiurazione', array['artefice', 'ranger', 'mago']::text[], '1 minuto o Rituale', '9 metri', '8 ore', 'V, S, M', 'una campanella e un filo d''argento', false, true, false, null, null, null, null, null, null, null, null, null, 'Si imposta un allarme contro le intrusioni. Scegliere una porta, una finestra o un’area entro il raggio d’azione che non sia più grande di un cubo di 6 metri. Fino al termine dell’incantesimo, un allarme avvisa ogni volta che una creatura tocca o entra nell’area protetta. Quando si lancia l’incantesimo, è possibile designare le creature che non faranno scattare l’allarme. Puoi anche scegliere se l’allarme sia udibile o mentale:

Allarme udibile. L’allarme produce il suono di una campanella per 10 secondi entro 18 metri dall’area protetta.

Allarme mentale. Se ti trovi entro 1 miglio dall’area protetta, ricevi un segnale mentale di avviso. Questo segnale ti sveglia se stai dormendo.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/alarm'),
    ('alter-incantatore', '2024', 'Alter Incantatore', 2, 'trasmutazione', array['artefice', 'stregone', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 1 ora', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Modifichi la tua forma fisica. Scegli una delle seguenti opzioni. I suoi effetti durano per tutta la durata dell’azione; durante questo periodo puoi compiere un’azione magica per sostituire l’opzione scelta con un’altra.

Adattamento acquatico. Ti spuntano le branchie e ti crescono delle membrane tra le dita. Puoi respirare sott’acqua e ottieni una velocità di nuoto pari alla tua velocità di movimento.

Cambia aspetto. Modifichi il tuo aspetto. Decidi tu come apparire, compresi altezza, peso, tratti del viso, timbro della voce, lunghezza dei capelli, colore e altre caratteristiche distintive. Puoi farti apparire come un membro di un’altra specie, anche se nessuna delle tue caratteristiche cambia. Non puoi assumere le sembianze di una creatura di dimensioni diverse e la tua forma di base rimane la stessa; se sei bipede, ad esempio, non puoi usare questo incantesimo per diventare quadrupede. Per tutta la durata, puoi compiere un’azione magica per modificare nuovamente il tuo aspetto in questo modo.

Armi naturali. Ti crescono artigli (da taglio), zanne (da perforazione), corna (da perforazione) o zoccoli (da contusione). Quando usi il tuo Attacco a mani nude per infliggere danni con quella nuova crescita, infliggi 1d6 danni del tipo indicato tra parentesi invece di infliggere il danno normale del tuo Attacco a mani nude, e usi il tuo modificatore di abilità di incantesimo per i tiri di attacco e di danno invece di usare la Forza.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/alter-Incantatore'),
    ('alustriel''s-mooncloak', '2024', 'Il Mantello Lunare di Alustriel', 5, 'abiurazione', array['bardo', 'druido', 'ranger', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 1 minuto', 'V, S, M', 'una pietra di luna del valore di 50+ GP', true, false, false, null, null, '4d10', null, null, null, null, null, null, 'Per tutta la durata dell’incantesimo, il chiaro di luna riempie un’emanazione di 6 metri che ha origine da te con Luce fioca. Mentre ti trovi in quell’area, tu e i tuoi alleati avete Mezza copertura e Resistenza ai danni da freddo, da fulmine e da radiante.

Mentre l’incantesimo dura, puoi utilizzare una delle seguenti opzioni, terminando immediatamente l’incantesimo:

Liberazione. Quando fallisci un tiro di salvataggio per evitare o porre fine alle condizioni “Spaventato”, “Afferrato” o “Immobilizzato”, puoi effettuare una Reazione per superare il tiro di salvataggio.

Tregua. Come azione magica, tu o un alleato all’interno dell’area recuperate Punti Ferita pari a 4d10 più il tuo modificatore di abilità di incantesimo.', 'Forgotten Realms: Heroes of Faerûn', 'https://5e-spellbook.app/spells/alustriel%27s-mooncloak'),
    ('animal-friendship', '2024', 'Amicizia con gli animali', 1, 'ammaliamento', array['bardo', 'druido', 'ranger']::text[], 'Azione', '9 metri', '24 ore', 'V, S, M', 'un boccone di cibo', false, false, false, 'wis', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una Bestia in più per ogni livello dello slot incantesimo superiore a 1.', 'Scegli come bersaglio una Bestia che puoi vedere entro il raggio d''azione. Il bersaglio deve superare un tiro salvezza di Saggezza oppure subire la condizione Incantato per tutta la durata dell''incantesimo. Se tu o uno dei tuoi alleati infliggete danni al bersaglio, l''incantesimo termina.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una Bestia in più per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/animal-friendship'),
    ('animal-messenger', '2024', 'Messaggero animale', 2, 'ammaliamento', array['bardo', 'druido', 'ranger']::text[], 'Azione o Rituale', '9 metri', '24 ore', 'V, S, M', 'un boccone di cibo', false, true, false, 'cha', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. La durata dell’incantesimo aumenta di 48 ore per ogni livello dello slot incantesimo superiore a 2.', 'Una Piccola Bestia a tua scelta che puoi vedere entro il raggio d''azione deve superare un tiro salvezza di Carisma, altrimenti tenterà di consegnare un messaggio per tuo conto (se il Grado di Sfida del bersaglio non è 0, il tiro ha automaticamente successo). Specifica un luogo che hai visitato e un destinatario che corrisponda a una descrizione generica, come “una persona che indossa l’uniforme della guardia cittadina” o “un nano dai capelli rossi con un cappello a punta”. Comunichi inoltre un messaggio di massimo venticinque parole. La Bestia viaggia per tutta la durata dell’incantesimo verso il luogo specificato, percorrendo circa 25 miglia ogni 24 ore o 50 miglia se la Bestia è in grado di volare.

Quando la Bestia arriva, consegna il tuo messaggio alla creatura che hai descritto, imitando il tuo modo di comunicare. Se la Bestia non raggiunge la sua destinazione prima che l’incantesimo finisca, il messaggio va perso e la Bestia ritorna nel luogo in cui hai lanciato l’incantesimo.

Utilizzo di uno slot incantesimo di livello superiore. La durata dell’incantesimo aumenta di 48 ore per ogni livello dello slot incantesimo superiore a 2.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/animal-messenger'),
    ('animal-shapes', '2024', 'Forme animali', 8, 'trasmutazione', array['druido']::text[], 'Azione', '9 metri', '24 ore', 'V, S', null, false, false, false, null, null, null, null, null, null, null, null, null, 'Scegli un numero qualsiasi di creature consenzienti che puoi vedere entro il raggio d''azione. Ogni bersaglio si trasforma in una Bestia di taglia Grande o inferiore a tua scelta, con un Indice di Sfida pari o inferiore a 4. Puoi scegliere una forma diversa per ciascun bersaglio. Nei turni successivi, puoi compiere un''azione magica per trasformare nuovamente i bersagli.

Le statistiche di gioco di un bersaglio vengono sostituite da quelle della Bestia scelta, ma il bersaglio mantiene il proprio tipo di creatura, i Punti Ferita, i Dadi dei Punti Ferita, l’allineamento, la capacità di comunicare e i punteggi di Intelligenza, Saggezza e Carisma. Le azioni del bersaglio sono limitate dall’anatomia della forma della Bestia e il bersaglio non può lanciare incantesimi. L’equipaggiamento del bersaglio si fonde con la nuova forma e il bersaglio non può utilizzare alcuna parte di quell’equipaggiamento mentre si trova in quella forma.

Il bersaglio ottiene un numero di Punti Ferita temporanei pari ai Punti Ferita della prima forma in cui si trasforma. Questi Punti Ferita temporanei svaniscono se ne rimangono quando l’incantesimo termina. La trasformazione dura per tutta la durata dell’incantesimo o fino a quando il bersaglio non la interrompe come Azione Bonus.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/animal-shapes'),
    ('animate-dead', '2024', 'Morti viventi', 3, 'necromanzia', array['chierico', 'mago']::text[], '1 minuto', '3 metri', 'Istantanea', 'V, S, M', 'una goccia di sangue, un pezzo di carne e un pizzico di polvere d’ossa', false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi animare o riprendere il controllo su due creature non morte aggiuntive per ogni livello di slot incantesimo superiore a 3. Ciascuna delle creature deve provenire da un cadavere o da un mucchio di ossa diverso.', 'Scegli un mucchio di ossa o il cadavere di un umanoide di taglia media o piccola entro il raggio d''azione. Il bersaglio diventa una creatura non morta: uno scheletro se hai scelto le ossa o uno zombie se hai scelto il cadavere.

In ciascuno dei tuoi turni, puoi compiere un''azione bonus per comandare mentalmente qualsiasi creatura che hai creato con questo incantesimo, purché si trovi entro 18 metri da te (se controlli più creature, puoi comandarle tutte contemporaneamente, impartendo lo stesso comando a ciascuna di esse). Decidi tu quale azione compirà la creatura e dove si muoverà nel suo prossimo turno, oppure puoi impartire un comando generico, come ad esempio sorvegliare una stanza o un corridoio. Se non impartisci alcun comando, la creatura esegue l’azione Schivare e si muove solo per evitare di subire danni. Una volta ricevuto un ordine, la creatura continua a seguirlo fino al completamento del compito.

La creatura rimane sotto il tuo controllo per 24 ore, dopodiché smette di obbedire a qualsiasi comando tu le abbia impartito. Per mantenere il controllo sulla creatura per altre 24 ore, devi lanciare nuovamente questo incantesimo sulla creatura prima che il periodo di 24 ore in corso giunga al termine. Questo utilizzo dell’incantesimo riafferma il tuo controllo su un massimo di quattro creature che hai animato con questo incantesimo, anziché animarne una nuova.

Utilizzo di uno slot incantesimo di livello superiore. Puoi animare o riprendere il controllo su due creature non morte aggiuntive per ogni livello di slot incantesimo superiore a 3. Ciascuna delle creature deve provenire da un cadavere o da un mucchio di ossa diverso.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/animate-dead'),
    ('animate-objects', '2024', 'Oggetti animati', 5, 'trasmutazione', array['artefice', 'bardo', 'stregone', 'mago']::text[], 'Azione', '36 metri', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, null, null, null, null, null, '1d4', null, 6, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno dell’Attacco della creatura aumenta di 1d4 (di taglia media o inferiore), 1d6 (grande) o 1d12 (enorme) per ogni livello dello slot incantesimo superiore a 5.', 'Gli oggetti prendono vita al tuo comando. Scegli un numero di oggetti non magici entro il raggio d’azione che non siano indossati o trasportati, non siano fissati a una superficie e non siano di taglia Gargantuan. Il numero massimo di oggetti è pari al tuo modificatore di abilità di incantesimo; ai fini di questo conteggio, un bersaglio di taglia Media o inferiore conta come un oggetto, uno di taglia Grande ne conta due e uno di taglia Enorme ne conta tre.

Ogni bersaglio si anima, gli spuntano le gambe e diventa un Costrutto che utilizza il blocco delle statistiche dell’Oggetto Animato; questa creatura è sotto il tuo controllo fino al termine dell’incantesimo o finché non viene ridotta a 0 Punti Ferita. Ogni creatura che crei con questo incantesimo è un alleato tuo e dei tuoi compagni. In combattimento, condivide il tuo valore di Iniziativa e agisce immediatamente dopo di te.

Fino al termine dell’incantesimo, puoi compiere un’azione bonus per comandare mentalmente qualsiasi creatura che hai creato con questo incantesimo, purché si trovi entro 150 metri da te (se controlli più creature, puoi comandarle tutte contemporaneamente, impartendo lo stesso comando a ciascuna di esse). Se non impartisci alcun comando, la creatura esegue l’azione Schivare e si muove solo per evitare di subire danni. Quando la creatura scende a 0 punti ferita, ritorna alla sua forma di oggetto e qualsiasi danno residuo viene trasferito a tale forma.

Utilizzo di uno slot incantesimo di livello superiore. Il danno dell’Attacco della creatura aumenta di 1d4 (di taglia media o inferiore), 1d6 (grande) o 1d12 (enorme) per ogni livello dello slot incantesimo superiore a 5.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/animate-objects'),
    ('antilife-shell', '2024', 'Guscio anti-vita', 5, 'abiurazione', array['druido']::text[], 'Azione', 'Personale', 'Concentrazione, 1 ora', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Per tutta la durata dell’incantesimo, un’aura si estende da te in un’emanazione di 3 metri. L’aura impedisce alle creature, ad eccezione dei Costrutti e dei Non Morti, di attraversarla o di raggiungerla. Una creatura interessata può lanciare incantesimi o effettuare attacchi con armi a distanza o a raggio attraverso la barriera.

Se ti sposti in modo tale che una creatura interessata sia costretta ad attraversare la barriera, l’incantesimo termina.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/antilife-shell'),
    ('antimagic-field', '2024', 'Campo antimagia', 8, 'abiurazione', array['chierico', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 1 ora', 'V, S, M', 'limatura di ferro', true, false, false, null, null, null, null, null, null, null, null, null, 'Un''aura antimagia ti circonda in un''emanazione di 3 metri. Nessuno può lanciare incantesimi, compiere azioni magiche o creare altri effetti magici all''interno dell''aura, e tali azioni non possono prendere di mira né influenzare in alcun modo ciò che si trova al suo interno. Le proprietà magiche degli oggetti magici non funzionano all''interno dell''aura né su nulla che si trovi al suo interno.

Le aree d’effetto create da incantesimi o da altra magia non possono estendersi all’interno dell’aura, e nessuno può teletrasportarsi al suo interno o fuori da essa né utilizzare il viaggio planare in tale zona. I portali si chiudono temporaneamente mentre ci si trova all’interno dell’aura.

Gli incantesimi attivi, eccetto quelli lanciati da un artefatto o da una divinità, vengono soppressi nell’area. Mentre un effetto è soppresso, non funziona, ma il tempo in cui rimane soppresso viene conteggiato ai fini della sua durata.

Dissolvi Magia non ha alcun effetto sull’aura, e le aure create da diversi incantesimi Campo Antimagico non si annullano a vicenda.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/antimagic-field'),
    ('antipathy/sympathy', '2024', 'Antipatia/Simpatia', 8, 'ammaliamento', array['bardo', 'druido', 'mago']::text[], '1 ora', '18 metri', '10 giorni', 'V, S, M', 'una miscela di aceto e miele', false, false, false, 'wis', null, null, null, null, null, null, null, null, 'Quando lanci l’incantesimo, scegli se esso generi antipatia o simpatia e scegli come bersaglio una creatura o un oggetto di taglia Enorme o inferiore. Quindi specifica un tipo di creatura, come draghi rossi, goblin o vampiri. Una creatura del tipo scelto effettua un tiro salvezza di Saggezza quando si avvicina a meno di 36 metri dal bersaglio. La tua scelta tra antipatia o simpatia determina cosa accade a una creatura quando fallisce quel tiro di salvataggio:

Antipatia. La creatura ha la condizione Spaventata. La creatura Spaventata deve usare il proprio movimento nei propri turni per allontanarsi il più possibile dal bersaglio, seguendo il percorso più sicuro.

Simpatia. La creatura si trova nella condizione “Incantata”. La creatura “Incantata” deve utilizzare il proprio movimento nei propri turni per avvicinarsi il più possibile al bersaglio, seguendo il percorso più sicuro. Se la creatura si trova entro 1,5 metri dal bersaglio, non può allontanarsi volontariamente. Se il bersaglio infligge danni alla creatura Incantata, quest’ultima può effettuare un tiro salvezza di Saggezza per porre fine all’effetto, come descritto di seguito.

Porre fine all’effetto. Se la creatura Spaventata o Incantata termina il proprio turno a più di 36 metri di distanza dal bersaglio, effettua un tiro salvezza di Saggezza. In caso di tiro di salvataggio riuscito, la creatura non è più influenzata dal bersaglio. Una creatura che supera con successo il tiro di salvataggio contro questo effetto ne è immune per 1 minuto, dopodiché può esserne nuovamente influenzata.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/antipathy%2Fsympathy'),
    ('arcane-eye', '2024', 'Occhio Arcano', 4, 'divinazione', array['artefice', 'mago']::text[], 'Azione', '9 metri', 'Concentrazione, 1 ora', 'V, S, M', 'un po’ di pelo di pipistrello', true, false, false, null, null, null, null, null, null, null, null, null, 'Crei un occhio invisibile e invulnerabile entro il raggio d''azione, che rimane sospeso per tutta la durata dell''incantesimo. Ricevi mentalmente le informazioni visive provenienti dall''occhio, che può vedere in ogni direzione. L''occhio possiede inoltre la visione nel buio con un raggio di 9 metri.

Come azione bonus, puoi spostare l’occhio fino a 9 metri in qualsiasi direzione. Una barriera solida blocca il movimento dell’occhio, ma l’occhio può passare attraverso un’apertura di appena 1 pollice di diametro.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/arcane-eye'),
    ('arcane-gate', '2024', 'Porta Arcana', 6, 'evocazione', array['stregone', 'warlock', 'mago']::text[], 'Azione', '150 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Crei dei portali di teletrasporto collegati. Scegli due spazi di dimensione Grande, liberi e visibili da te, uno entro il raggio d’azione e l’altro entro 3 metri da te. In ciascuno di questi spazi si apre un portale circolare che rimane attivo per tutta la durata dell’incantesimo.

I portali sono anelli luminosi bidimensionali pieni di nebbia che ostacola la vista. Si librano a pochi pollici dal suolo e sono perpendicolari ad esso.

Un portale è aperto su un solo lato (scelto da te). Qualsiasi cosa entri dal lato aperto di un portale esce dal lato aperto dell’altro portale come se i due fossero adiacenti l’uno all’altro. Come azione bonus, puoi cambiare l’orientamento dei lati aperti.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/arcane-gate'),
    ('arcane-lock', '2024', 'Serratura arcana', 2, 'abiurazione', array['artefice', 'mago']::text[], 'Azione', 'Contatto', 'Finché non viene dissolto', 'V, S, M', 'polvere d’oro del valore di 25+ GP, che l’incantesimo consuma', false, false, false, null, null, null, null, null, null, null, null, null, 'Tocchi una porta, una finestra, un cancello, un contenitore o un portello chiusi e li chiudi magicamente per tutta la durata dell’incantesimo. Questa chiusura non può essere aperta con alcun mezzo non magico. Tu e qualsiasi creatura da te designata al momento del lancio dell’incantesimo potete aprire e chiudere l’oggetto nonostante il blocco. Puoi anche impostare una password che, se pronunciata entro 1,5 metri dall’oggetto, lo sblocca per 1 minuto.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/arcane-lock'),
    ('arcane-vigor', '2024', 'Vigore Arcano', 2, 'abiurazione', array['artefice', 'stregone', 'mago']::text[], 'Azione bonus', 'Personale', 'Istantanea', 'V, S', null, false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Il numero di dadi vita non utilizzati che puoi tirare aumenta di uno per ogni livello dello slot incantesimo superiore a 2.', 'Attingi alla tua forza vitale per curarti. Lancia uno o due dei tuoi dadi dei Punti Ferita non ancora utilizzati e recupera un numero di Punti Ferita pari al totale del tiro più il tuo modificatore di abilità di incantesimo. Quei dadi vengono quindi consumati.

Utilizzo di uno slot incantesimo di livello superiore. Il numero di dadi vita non utilizzati che puoi tirare aumenta di uno per ogni livello dello slot incantesimo superiore a 2.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/arcane-vigor'),
    ('armor-of-agathys', '2024', 'Armatura di Agathys', 1, 'abiurazione', array['warlock']::text[], 'Azione bonus', 'Personale', '1 ora', 'V, S, M', 'un frammento di vetro blu', false, false, false, null, null, null, null, 'freddo', null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. I punti ferita temporanei e il danno da freddo aumentano entrambi di 5 per ogni livello dello slot incantesimo superiore a 1.', 'Una barriera magica di gelo ti circonda. Ottieni 5 Punti Ferita temporanei. Se una creatura ti colpisce con un tiro per colpire in mischia prima che l’incantesimo finisca, la creatura subisce 5 danni da freddo. L’incantesimo termina anticipatamente se non hai più Punti Ferita temporanei.

Utilizzo di uno slot incantesimo di livello superiore. I punti ferita temporanei e il danno da freddo aumentano entrambi di 5 per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/armor-of-agathys'),
    ('arms-of-hadar', '2024', 'Armi di Hadar', 1, 'evocazione', array['warlock']::text[], 'Azione', 'Personale', 'Istantanea', 'V, S', null, false, false, false, 'str', null, '2d6', null, 'necrotico', '1d6', null, 2, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d6 per ogni livello dello slot incantesimo superiore a 1.', 'Invocando Hadar, fai sì che dei viticci spuntino dal tuo corpo. Ogni creatura che si trova in un’area di emanazione di 3 metri con centro in te effettua un tiro salvezza di Forza. In caso di fallimento del tiro salvezza, il bersaglio subisce 2d6 danni necrotici e non può effettuare Reazioni fino all’inizio del suo prossimo turno. In caso di tiro di salvataggio riuscito, il bersaglio subisce solo la metà dei danni.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d6 per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/arms-of-hadar'),
    ('astral-projection', '2024', 'Proiezione astrale', 9, 'necromanzia', array['chierico', 'warlock', 'mago']::text[], '1 ora', '3 metri', 'Finché non viene dissolto', 'V, S, M', 'per ciascuno dei bersagli dell’incantesimo, un giacinto del valore di 1.000+ PO e un lingotto d’argento del valore di 100+ PO, che l’incantesimo consuma interamente', false, false, false, null, null, null, null, null, null, null, null, null, 'Tu e fino a otto creature consenzienti entro il raggio d''azione proiettate i vostri corpi astrali nel Piano Astrale (l''incantesimo termina immediatamente se vi trovate già su quel piano). Il corpo di ciascun bersaglio viene lasciato indietro in uno stato di animazione sospesa; si trova nella condizione Incosciente, non ha bisogno di cibo né di aria e non invecchia.

La forma astrale di un bersaglio assomiglia al suo corpo sotto quasi ogni aspetto, replicandone le statistiche di gioco e i beni. La differenza principale è l’aggiunta di un cordone argenteo che si estende da tra le scapole della forma astrale. Il cordone scompare dalla vista dopo 0,3 metri. Se il cordone viene reciso — cosa che accade solo quando un effetto lo prevede — sia il corpo che la forma astrale del bersaglio muoiono.

La forma astrale di un bersaglio può viaggiare attraverso il Piano Astrale. Nel momento in cui una forma astrale lascia quel piano, il corpo e gli effetti personali del bersaglio viaggiano lungo il cordone argentato, facendo sì che il bersaglio rientri nel proprio corpo nel nuovo piano.

Qualsiasi danno o altro effetto che si applichi a una forma astrale non ha alcun effetto sul corpo del bersaglio e viceversa. Se il corpo o la forma astrale di un bersaglio scendono a 0 Punti Ferita, l’incantesimo termina per quel bersaglio. L’incantesimo termina per tutti i bersagli se compi un’azione magica per dissolverlo.

Quando l’incantesimo termina per un bersaglio che non è morto, il bersaglio riappare nel proprio corpo ed esce dallo stato di animazione sospesa.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/astral-projection'),
    ('augury', '2024', 'Augurio', 2, 'divinazione', array['chierico', 'druido', 'mago']::text[], '1 minuto o Rituale', 'Personale', 'Istantanea', 'V, S, M', 'bastoncini, ossa, carte o altri oggetti divinatori appositamente contrassegnati del valore di 25+ PO', false, true, false, null, null, null, null, null, null, null, null, null, 'Ricevi un presagio da un''entità ultraterrena riguardo all''esito di un''azione che intendi compiere entro i prossimi 30 minuti. Il DM sceglie il presagio dalla tabella dei Presagi.

Presagi

Presagio

Per esiti che saranno...

Fortuna

Buoni

Sventura

Cattivi

Fortuna e sventura

Buoni e cattivi

Indifferenza

Né buoni né cattivi

L''incantesimo non tiene conto di circostanze, come altri incantesimi, che potrebbero modificare i risultati.

Se lanci l’incantesimo più di una volta prima di terminare un Riposo Lungo, c’è una probabilità cumulativa di 25 per ogni lancio successivo al primo di non ottenere alcuna risposta.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/augury'),
    ('aura-of-evasion', '2024', 'Aura di Evasione', 7, 'abiurazione', array['stregone', 'warlock', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, 'dex', null, null, null, null, null, null, null, null, 'Per tutta la durata dell’effetto, da te si irradia un’aura di alacrità in un’emanazione di 9 metri. All’interno dell’aura, tu e i tuoi alleati avete Vantaggio sui tiri salvezza di Destrezza. Quando una creatura interessata è soggetta a un effetto che le consente di effettuare un tiro salvezza di Destrezza per subire solo metà dei danni, non subisce alcun danno se supera il tiro salvezza e subisce solo metà dei danni se lo fallisce. Una creatura con la condizione Incapacitata non ottiene alcun beneficio dall’essere all’interno dell’aura.', 'Arcana Unleashed', 'https://5e-spellbook.app/spells/aura-of-evasion'),
    ('aura-of-life', '2024', 'Aura della Vita', 4, 'abiurazione', array['chierico', 'paladino']::text[], 'Azione', 'Personale', 'Concentrazione, 10 minuti', 'V', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Per tutta la durata dell’effetto, da te si irradia un’aura con un raggio di 9 metri. All’interno dell’aura, tu e i tuoi alleati avete Resistenza al danno necrotico e il vostro massimo di Punti Ferita non può essere ridotto. Se un alleato con 0 Punti Ferita inizia il proprio turno all’interno dell’aura, quell’alleato recupera 1 Punto Ferita.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/aura-of-life'),
    ('aura-of-purity', '2024', 'Aura di Purezza', 4, 'abiurazione', array['chierico', 'paladino']::text[], 'Azione', 'Personale', 'Concentrazione, 10 minuti', 'V', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Per tutta la durata dell’effetto, da te si irradia un’aura in un’emanazione di 9 metri. All’interno dell’aura, tu e i tuoi alleati avete Resistenza al danno da veleno e Vantaggio sui tiri salvezza per evitare o porre fine agli effetti che includono le condizioni Accecato, Incantato, Assordato, Spaventato, Paralizzato, Avvelenato o Stordito.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/aura-of-purity'),
    ('aura-of-vitality', '2024', 'Aura di vitalità', 3, 'abiurazione', array['chierico', 'druido', 'paladino']::text[], 'Azione', 'Personale', 'Concentrazione, 1 minuto', 'V', null, true, false, false, null, null, '2d6', null, null, null, null, null, null, 'Per tutta la durata dell’effetto, da te si irradia un’aura in un’area di emanazione di 9 metri. Quando crei l’aura e all’inizio di ciascuno dei tuoi turni mentre essa persiste, puoi ripristinare 2d6 punti ferita a una creatura che si trova al suo interno.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/aura-of-vitality'),
    ('awaken', '2024', 'Risveglio', 5, 'trasmutazione', array['bardo', 'druido']::text[], '8 ore', 'Contatto', 'Istantanea', 'V, S, M', 'un''agata del valore di oltre 1.000 PO, che l''incantesimo consuma', false, false, false, null, null, null, null, null, null, null, null, null, 'Trascorri il tempo di lancio tracciando percorsi magici all’interno di una gemma preziosa, quindi tocchi il bersaglio. Il bersaglio deve essere una creatura di tipo Bestia o Pianta con un’Intelligenza pari o inferiore a 3 oppure una pianta naturale che non sia una creatura. Il bersaglio ottiene un''Intelligenza pari a 10 e la capacità di parlare una lingua che conosci. Se il bersaglio è una pianta naturale, diventa una creatura di tipo Pianta e acquisisce la capacità di muovere i propri rami, radici, rampicanti, viticci e così via, oltre a sviluppare sensi simili a quelli umani. Il DM sceglie le caratteristiche appropriate per la pianta risvegliata, come quelle dell’Arbusto Risvegliato o dell’Albero Risvegliato riportate nel Manuale dei Mostri.

Il bersaglio risvegliato ha la condizione Incantato per 30 giorni o finché tu o i tuoi alleati non gli infliggete danni. Quando tale condizione termina, la creatura risvegliata sceglie il proprio atteggiamento nei tuoi confronti.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/awaken'),
    ('backlash', '2024', 'Backlash', 4, 'abiurazione', array['bardo', 'stregone', 'warlock', 'mago']::text[], 'Reazione che si intraprende in risposta al fatto di aver subito danni', '18 metri', 'Istantanea', 'V', null, false, false, false, 'con', null, '4d6', null, 'forza', '1d6', null, 5, 'Utilizzo di uno slot incantesimo di livello superiore. Sia la riduzione del danno che il danno da Forza di questo incantesimo aumentano di 1d6 per ogni livello dello slot incantesimo superiore a 4.', 'Ti proteggi dall’energia distruttiva, riducendo il danno subito di 4d6 più il tuo modificatore di Abilità di Incantesimo.

Se il danno che ha attivato l’incantesimo proveniva da una creatura entro il raggio d’azione, puoi costringere la creatura a effettuare un tiro salvezza di Costituzione. La creatura subisce 4d6 danni da Forza in caso di fallimento del tiro salvezza o metà di tale danno in caso di successo.

Utilizzo di uno slot incantesimo di livello superiore. Sia la riduzione del danno che il danno da Forza di questo incantesimo aumentano di 1d6 per ogni livello dello slot incantesimo superiore a 4.', 'Forgotten Realms: Heroes of Faerûn', 'https://5e-spellbook.app/spells/backlash'),
    ('bane', '2024', 'Bane', 1, 'ammaliamento', array['bardo', 'chierico', 'warlock']::text[], 'Azione', '9 metri', 'Concentrazione, 1 minuto', 'V, S, M', 'una goccia di sangue', true, false, false, 'cha', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Fino a tre creature a tua scelta che puoi vedere entro il raggio d''azione devono effettuare ciascuna un tiro salvezza di Carisma. Ogni volta che un bersaglio che fallisce questo tiro salvezza effettua un tiro per colpire o un tiro salvezza prima che l''incantesimo finisca, il bersaglio deve sottrarre 1d4 dal tiro per colpire o dal tiro salvezza.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/bane'),
    ('banishing-smite', '2024', 'Colpo di bandimento', 5, 'evocazione', array['paladino']::text[], 'Azione bonus che si esegue immediatamente dopo aver colpito una creatura con un''arma da mischia o un attacco a mani nude', 'Personale', 'Concentrazione, 1 minuto', 'V', null, true, false, false, 'cha', null, '5d10', null, 'forza', null, null, null, null, 'Il bersaglio colpito dal tiro per colpire subisce 5d10 danni da Forza aggiuntivi dall’attacco. Se l’attacco riduce i Punti Ferita del bersaglio a 50 o meno, il bersaglio deve superare un tiro salvezza di Carisma o viene trasportato in un demipiano innocuo per tutta la durata dell’incantesimo. Mentre si trova lì, il bersaglio ha la condizione Incapacitato. Al termine dell’incantesimo, il bersaglio riappare nello spazio che ha lasciato o nello spazio libero più vicino, se quello è occupato.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/banishing-smite'),
    ('banishment', '2024', 'Esilio', 4, 'abiurazione', array['chierico', 'paladino', 'stregone', 'warlock', 'mago']::text[], 'Azione', '9 metri', 'Concentrazione, 1 minuto', 'V, S, M', 'un pentacolo', true, false, false, 'cha', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello di slot incantesimo superiore a 4.', 'Una creatura che puoi vedere entro il raggio d''azione deve superare un tiro salvezza di Carisma o verrà trasportata in un demiplano innocuo per tutta la durata dell''incantesimo. Mentre si trova lì, il bersaglio ha la condizione Incapacitato. Quando l''incantesimo termina, il bersaglio riappare nello spazio che ha lasciato o nello spazio libero più vicino se quello è occupato.

Se il bersaglio è un’Aberrazione, un Celestiale, un Elementale, un Fata o un Demone, non ritorna se l’incantesimo dura 1 minuto. Il bersaglio viene invece trasportato in una posizione casuale su un piano (a scelta del DM) associato al suo tipo di creatura.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello di slot incantesimo superiore a 4.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/banishment'),
    ('barkskin', '2024', 'Barkskin', 2, 'trasmutazione', array['druido', 'ranger']::text[], 'Azione bonus', 'Contatto', '1 ora', 'V, S, M', 'una manciata di corteccia di quercia', false, false, false, null, null, null, null, null, null, null, null, null, 'Tocchi una creatura consenziente. Fino al termine dell’incantesimo, la pelle del bersaglio assume un aspetto simile alla corteccia e il bersaglio ha una Classe Armatura pari a 17 se la sua CA è inferiore a tale valore.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/barkskin'),
    ('battle-familiar', '2024', 'Familiare da battaglia', 2, 'evocazione', array['druido', 'warlock', 'mago']::text[], 'Azione', '3 metri', '1 ora', 'V, S, M', 'un diamante del valore di 25+ PO', false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Utilizza il livello dello slot incantesimo come livello dell’incantesimo nel blocco delle statistiche.', 'Evoca un famiglio dotato di potere magico. Il famiglio appare in uno spazio libero entro il raggio d’azione; assomiglia a un animale a tua scelta ma è un Celestiale, un Fata o un Demone (a tua scelta); e utilizza il blocco delle caratteristiche del Famiglio da Battaglia. Quando lanci questo incantesimo, scegli la forma Bruto, Volatore o Predatore. La scelta determina alcuni dettagli nel blocco delle statistiche.

Combattimento. Il famiglio è un alleato tuo e dei tuoi compagni. Tira la propria Iniziativa e agisce nel proprio turno.

Scomparsa del famiglio. Il famiglio da battaglia scompare quando l’incantesimo termina, se i suoi Punti Ferita scendono a 0 o se muori. Quando scompare, lascia nel proprio spazio qualsiasi oggetto indossasse o trasportasse. Se lanci nuovamente questo incantesimo, decidi se evocare il famiglio che è scomparso o uno diverso.

Un solo famiglio alla volta. Non puoi avere più di un famiglio alla volta. Se lanci questo incantesimo mentre hai già un famiglio ottenuto con questo incantesimo, quel famiglio viene sostituito da quello nuovo.

Se quando lanci questo incantesimo hai già un famiglio ottenuto con l’incantesimo Trova famiglio, potenzi il tuo famiglio esistente invece di evocarne uno nuovo. Per tutta la durata, il tuo famiglio può attaccare oltre a compiere altre azioni come di consueto, e le sue statistiche di gioco vengono sostituite dal blocco statistico “Famiglio da battaglia”, ma mantiene il proprio tipo di creatura, allineamento, Punti Ferita, Dadi dei Punti Ferita ed eventuali caratteristiche concesse dall’incantesimo “Trova famiglio”. Il tuo famiglio ottiene un numero di Punti Ferita temporanei pari ai Punti Ferita del famiglio da battaglia. L’incantesimo “Famiglio da battaglia” termina anticipatamente se il famiglio non ha più Punti Ferita temporanei, e questi Punti Ferita temporanei svaniscono se ne rimangono quando l’incantesimo termina. Il tuo famiglio ritorna alla sua forma precedente quando l’incantesimo “Famiglio da battaglia” termina.

Utilizzo di uno slot incantesimo di livello superiore. Utilizza il livello dello slot incantesimo come livello dell’incantesimo nel blocco delle statistiche.', 'Arcana Unleashed', 'https://5e-spellbook.app/spells/battle-familiar'),
    ('beacon-of-hope', '2024', 'Faro di speranza', 3, 'abiurazione', array['chierico']::text[], 'Azione', '9 metri', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Scegli un numero qualsiasi di creature entro il raggio d''azione. Per tutta la durata dell''effetto, ogni bersaglio ottiene Vantaggio sui tiri salvezza di Saggezza e sui tiri salvezza contro la morte e recupera il numero massimo di Punti Ferita possibili da qualsiasi cura.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/beacon-of-hope'),
    ('beast-sense', '2024', 'Beast Sense', 2, 'divinazione', array['druido', 'ranger']::text[], 'Azione o Rituale', 'Contatto', 'Concentrazione, 1 ora', 'S', null, true, true, false, null, null, null, null, null, null, null, null, null, 'Tocchi una Bestia consenziente. Per tutta la durata dell’effetto, puoi percepire attraverso i sensi della Bestia oltre che attraverso i tuoi. Quando percepisci attraverso i sensi della Bestia, benefici di eventuali sensi speciali di cui essa dispone.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/beast-sense'),
    ('befuddlement', '2024', 'Confusione', 8, 'ammaliamento', array['bardo', 'druido', 'warlock', 'mago']::text[], 'Azione', '45 metri', 'Istantanea', 'V, S, M', 'un portachiavi senza chiavi', false, false, false, 'int', null, '10d12', null, 'psichico', null, null, null, null, 'Colpisci la mente di una creatura che puoi vedere entro il raggio d''azione. Il bersaglio effettua un tiro salvezza di Intelligenza.

In caso di fallimento del tiro salvezza, il bersaglio subisce 10d12 danni psichici e non può lanciare incantesimi né compiere l’azione Magia. Alla fine di ogni 30 giorni, il bersaglio ripete il tiro di salvataggio; in caso di successo, l’effetto termina. L’effetto può essere interrotto anche dagli incantesimi Restauro Maggiore, Guarigione o Desiderio.

In caso di successo al tiro di salvataggio, il bersaglio subisce solo la metà dei danni.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/befuddlement'),
    ('bestow-curse', '2024', 'Infliggere una maledizione', 3, 'necromanzia', array['bardo', 'chierico', 'mago']::text[], 'Azione', 'Contatto', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, 'wis', null, '1d8', null, 'necrotico', null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Se lanci questo incantesimo utilizzando uno slot incantesimo di livello 4, puoi mantenere la Concentrazione su di esso per un massimo di 10 minuti. Se utilizzi uno slot incantesimo di livello 5 o superiore, l’incantesimo non richiede Concentrazione e la durata diventa di 8 ore (slot di livello 5-6) o di 24 ore (slot di livello 7-8). Se utilizzi uno slot incantesimo di livello 9, l’incantesimo dura fino a quando non viene dissipato.', 'Tocchi una creatura, che deve superare un tiro salvezza di Saggezza o rimanere maledetta per tutta la durata dell’effetto. Finché la maledizione non termina, il bersaglio subisce uno dei seguenti effetti a tua scelta:

Scegli un’abilità. Il bersaglio ha Svantaggio sui tiri di abilità e sui tiri salvezza effettuati con quell’abilità.

Il bersaglio ha Svantaggio sui tiri per colpire contro di te.

In combattimento, il bersaglio deve superare un tiro salvezza di Saggezza all’inizio di ciascuno dei suoi turni, altrimenti è costretto a compiere l’azione Schivare in quel turno.

Se infliggi danni al bersaglio con un tiro per colpire o un incantesimo, il bersaglio subisce 1d8 danni necrotici aggiuntivi.

Utilizzo di uno slot incantesimo di livello superiore. Se lanci questo incantesimo utilizzando uno slot incantesimo di livello 4, puoi mantenere la Concentrazione su di esso per un massimo di 10 minuti. Se utilizzi uno slot incantesimo di livello 5 o superiore, l’incantesimo non richiede Concentrazione e la durata diventa di 8 ore (slot di livello 5-6) o di 24 ore (slot di livello 7-8). Se utilizzi uno slot incantesimo di livello 9, l’incantesimo dura fino a quando non viene dissipato.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/bestow-curse'),
    ('bigby''s-hand', '2024', 'La Mano di Bigby', 5, 'invocazione', array['artefice', 'stregone', 'mago']::text[], 'Azione', '36 metri', 'Concentrazione, 1 minuto', 'V, S, M', 'un guscio d’uovo e un guanto', true, false, true, 'str', 'melee', '5d8', null, 'forza', '2d8', null, 6, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno di «Pugno serrato» aumenta di 2d8 e il danno di «Mano avida» aumenta di 2d6 per ogni livello dello slot incantesimo superiore a 5.', 'Crei una mano di grandi dimensioni, fatta di energia magica scintillante, in uno spazio libero che puoi vedere entro il raggio d''azione. La mano rimane attiva per tutta la durata dell''incantesimo e si muove secondo i tuoi comandi, imitando i movimenti della tua stessa mano.

La mano è un oggetto con una Classe di Armatura (CA) pari a 20 e Punti Ferita pari al tuo massimo di Punti Ferita. Se i suoi Punti Ferita scendono a 0, l’incantesimo termina. La mano non occupa spazio.

Quando lanci l’incantesimo e come Azione Bonus nei tuoi turni successivi, puoi spostare la mano fino a 18 metri e poi provocare uno dei seguenti effetti:

Pugno chiuso. La mano colpisce un bersaglio entro 1,5 metri da essa. Effettua un attacco magico in mischia. In caso di colpo, il bersaglio subisce 5d8 danni da Forza.

Mano potente. La mano tenta di spingere una creatura di taglia Enorme o inferiore entro 1,5 metri da essa. Il bersaglio deve superare un tiro salvezza di Forza, altrimenti la mano lo spinge fino a 1,5 metri più un numero di piedi pari a cinque volte il tuo modificatore all’abilità di incantesimo. La mano si sposta insieme al bersaglio, rimanendo entro 1,5 metri da esso.

Mano che afferra. La mano tenta di afferrare una creatura di taglia Enorme o inferiore che si trovi entro 1,5 metri da essa. Il bersaglio deve superare un tiro salvezza di Destrezza; in caso contrario, il bersaglio subisce la condizione “Afferrato”, con una CD di fuga pari alla tua CD di salvataggio incantamento. Mentre la mano tiene in presa il bersaglio, puoi compiere un’azione bonus per far sì che la mano lo schiacci, infliggendo al bersaglio un danno da contusione pari a 4d6 più il tuo modificatore di abilità di incantesimo.

Mano Interpositiva. La mano ti garantisce mezza copertura contro attacchi e altri effetti che hanno origine dal suo spazio o che lo attraversano. Inoltre, il suo spazio conta come terreno difficile per i tuoi nemici.

Utilizzo di uno slot incantesimo di livello superiore. Il danno di «Pugno serrato» aumenta di 2d8 e il danno di «Mano avida» aumenta di 2d6 per ogni livello dello slot incantesimo superiore a 5.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/bigby%27s-hand'),
    ('blade-barrier', '2024', 'Barriera di lame', 6, 'invocazione', array['chierico']::text[], 'Azione', '27 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'dex', null, '6d10', null, 'forza', null, null, null, null, 'Crei un muro di lame vorticose fatto di energia magica. Il muro appare entro il raggio d’azione e dura per tutta la durata. Puoi creare un muro rettilineo lungo fino a 30 metri, alto 6 metri e spesso 1,5 metri, oppure un muro circolare con un diametro massimo di 18 metri, alto 6 metri e spesso 1,5 metri. Il muro offre copertura a tre quarti e il suo spazio è considerato terreno difficile.

Qualsiasi creatura che si trovi nello spazio del muro effettua un tiro salvezza di Destrezza, subendo 6d10 danni da Forza in caso di fallimento o metà dei danni in caso di successo. Una creatura effettua tale tiro salvezza anche se entra nello spazio del muro o vi termina il proprio turno. Una creatura effettua tale tiro salvezza solo una volta per turno.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/blade-barrier'),
    ('blade-of-disaster', '2024', 'Lama del Disastro', 9, 'evocazione', array['stregone', 'warlock', 'mago']::text[], 'Azione bonus', '18 metri', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, null, null, '10d6', null, 'forza', null, null, null, null, 'Crei una fenditura planare a forma di lama lunga 0,9 metri che dura per tutta la durata dell’incantesimo. La fenditura appare entro il raggio d’azione in uno spazio a tua scelta e puoi effettuare immediatamente fino a due attacchi magici in mischia, ciascuno contro una creatura o un oggetto entro 1,5 metri dalla fenditura. In caso di colpo andato a segno, il bersaglio subisce 10d6 danni da Forza. Questo attacco ottiene un colpo critico se il risultato del d20 è pari o superiore a 18.

Come azione bonus nei tuoi turni successivi, puoi spostare la fenditura fino a 18 metri e ripetere i due attacchi contro una creatura o un oggetto entro 1,5 metri da essa. Puoi dirigere gli attacchi contro lo stesso bersaglio o contro bersagli diversi.

La lama può attraversare indenne qualsiasi barriera, comprese quelle create da incantesimi come «Muro di Forza».', 'Forgotten Realms: Heroes of Faerûn', 'https://5e-spellbook.app/spells/blade-of-disaster'),
    ('blade-ward', '2024', 'Blade Ward', 0, 'abiurazione', array['bardo', 'stregone', 'warlock', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Ogni volta che una creatura effettua un tiro per colpire contro di te prima che l’incantesimo finisca, l’attaccante sottrae 1d4 dal tiro per colpire.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/blade-ward'),
    ('bless', '2024', 'Benedizione', 1, 'ammaliamento', array['chierico', 'paladino']::text[], 'Azione', '9 metri', 'Concentrazione, 1 minuto', 'V, S, M', 'un Simbolo Sacro del valore di 5+ PO', true, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Benedici fino a tre creature entro il raggio d''azione. Ogni volta che un bersaglio effettua un tiro per colpire o un tiro salvezza prima che l''incantesimo finisca, il bersaglio aggiunge 1d4 al tiro per colpire o al tiro salvezza.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/bless'),
    ('blight', '2024', 'Blight', 4, 'necromanzia', array['druido', 'stregone', 'warlock', 'mago']::text[], 'Azione', '9 metri', 'Istantanea', 'V, S', null, false, false, false, 'con', null, '8d8', null, 'necrotico', '1d8', null, 5, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 4.', 'Una creatura che puoi vedere entro il raggio d''azione effettua un tiro salvezza di Costituzione, subendo 8d8 danni necrotici in caso di fallimento o metà dei danni in caso di successo. Una creatura vegetale fallisce automaticamente il tiro salvezza.

In alternativa, scegli come bersaglio una pianta non magica che non sia una creatura, come un albero o un arbusto. Essa non effettua alcun tiro salvezza; semplicemente appassisce e muore.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 4.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/blight'),
    ('blinding-smite', '2024', 'Colpo accecante', 3, 'invocazione', array['paladino']::text[], 'Azione bonus che si esegue immediatamente dopo aver colpito una creatura con un''arma da mischia o un attacco a mani nude', 'Personale', '1 minuto', 'V', null, false, false, false, 'con', null, '3d8', null, 'radioso', '1d8', null, 4, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aggiuntivo aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 3.', 'Il bersaglio colpito dall’attacco subisce 3d8 danni radianti aggiuntivi e rimane in condizioni di Accecamento fino al termine dell’incantesimo. Alla fine di ciascuno dei propri turni, il bersaglio Accecato effettua un tiro salvezza di Costituzione; in caso di successo, l’incantesimo su di sé termina.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aggiuntivo aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 3.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/blinding-smite'),
    ('blindness/deafness', '2024', 'Cecità/Sordità', 2, 'trasmutazione', array['bardo', 'chierico', 'stregone', 'mago']::text[], 'Azione', '36 metri', '1 minuto', 'V', null, false, false, false, 'con', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 2.', 'Una creatura che puoi vedere entro il raggio d''azione deve superare un tiro salvezza di Costituzione, altrimenti subisce la condizione Accecato o Assordato (a tua scelta) per tutta la durata dell''incantesimo. Alla fine di ciascuno dei suoi turni, il bersaglio ripete il tiro salvezza e, in caso di successo, l''incantesimo su di esso termina.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 2.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/blindness%2Fdeafness'),
    ('blink', '2024', 'Blink', 3, 'trasmutazione', array['artefice', 'stregone', 'mago']::text[], 'Azione', 'Personale', '1 minuto', 'V, S', null, false, false, false, null, null, null, null, null, null, null, null, null, 'Tira 1d6 alla fine di ciascuno dei tuoi turni per tutta la durata dell’incantesimo. Con un risultato compreso tra 4 e 6, svanisci dal tuo attuale piano di esistenza e appari nel Piano Etereo (l’incantesimo termina immediatamente se ti trovi già su quel piano). Mentre ti trovi nel Piano Etereo, puoi percepire il piano che hai lasciato, che appare in sfumature di grigio, ma non puoi vedere nulla che si trovi a più di 18 metri di distanza. Puoi influenzare ed essere influenzato solo da altre creature presenti nel Piano Etereo, e le creature dell’altro piano non possono percepirti a meno che non abbiano un’abilità speciale che consenta loro di percepire ciò che si trova nel Piano Etereo.

Ritorni nell’altro piano all’inizio del tuo prossimo turno e quando l’incantesimo termina, se ti trovi nel Piano Etereo. Ritorni in uno spazio libero a tua scelta che puoi vedere entro 3 metri dallo spazio che hai lasciato. Se non è disponibile alcuno spazio libero entro tale raggio, appari nello spazio libero più vicino.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/blink'),
    ('blur', '2024', 'Blur', 2, 'illusione', array['artefice', 'stregone', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 1 minuto', 'V', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Il tuo corpo diventa sfocato. Per tutta la durata dell’effetto, qualsiasi creatura subisce Svantaggio nei tiri per colpire contro di te. Un attaccante è immune a questo effetto se ti percepisce tramite Vista cieca o Vista vera.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/blur'),
    ('burning-hands', '2024', 'Mani brucianti', 1, 'invocazione', array['stregone', 'mago']::text[], 'Azione', 'Incantatore (cono di 4,5 metri)', 'Istantanea', 'V, S', null, false, false, false, 'dex', null, '3d6', null, 'fuoco', '1d6', null, 2, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d6 per ogni livello dello slot incantesimo superiore a 1.', 'Da te si sprigiona un sottile getto di fiamme. Ogni creatura all’interno di un cono di 4,5 metri effettua un tiro salvezza di Destrezza, subendo 3d6 danni da fuoco in caso di fallimento o metà dei danni in caso di successo.

Gli oggetti infiammabili presenti nel cono che non vengono indossati o trasportati prendono fuoco.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d6 per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/burning-hands'),
    ('cacophonic-shield', '2024', 'Scudo cacofonico', 3, 'invocazione', array['bardo', 'stregone', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'con', null, '3d6', null, 'tuono', '1d6', null, 4, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d6 per ogni livello dello slot incantesimo superiore a 3.', 'Per tutta la durata dell’effetto, riverberi fragorosi riempiono un’Emanazione di 3 metri che ha origine da te. Ogni volta che l’Emanazione entra nello spazio di una creatura e ogni volta che una creatura entra nell’Emanazione o termina il proprio turno al suo interno, la creatura effettua un tiro salvezza di Costituzione. In caso di tiro di salvataggio fallito, la creatura subisce 3d6 danni da Tuono e si trova nella condizione di Sordità fino all’inizio del tuo prossimo turno. In caso di tiro di salvataggio riuscito, la creatura subisce solo la metà dei danni. Una creatura effettua questo tiro di salvataggio solo una volta per turno. Quando lanci questo incantesimo, puoi designare delle creature che non ne subiscano gli effetti.

Inoltre, hai Resistenza al danno da Tuono e i tiri per colpire a distanza contro di te vengono effettuati con Svantaggio.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d6 per ogni livello dello slot incantesimo superiore a 3.', 'Forgotten Realms: Heroes of Faerûn', 'https://5e-spellbook.app/spells/cacophonic-shield'),
    ('call-lightning', '2024', 'Evoca fulmine', 3, 'evocazione', array['druido']::text[], 'Azione', '36 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'dex', null, '3d10', null, 'fulmine', '1d10', null, 4, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d10 per ogni livello dello slot incantesimo superiore a 3.', 'Una nuvola temporalesca appare in un punto entro il raggio d''azione che puoi vedere sopra di te. Assume la forma di un cilindro alto 3 metri con un raggio di 18 metri.

Quando lanci l''incantesimo, scegli un punto che puoi vedere sotto la nuvola. Un fulmine scocca dalla nuvola verso quel punto. Ogni creatura entro 1,5 metri da quel punto effettua un tiro salvezza di Destrezza, subendo 3d10 danni da fulmine in caso di fallimento o metà dei danni in caso di successo.

Fino al termine dell’incantesimo, puoi compiere un’azione magica per far scendere nuovamente un fulmine in questo modo, mirando allo stesso punto o a uno diverso.

Se ti trovi all’aperto durante un temporale quando lanci questo incantesimo, l’incantesimo ti permette di controllare quel temporale invece di crearne uno nuovo. In tali condizioni, il danno dell’incantesimo aumenta di 1d10.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d10 per ogni livello dello slot incantesimo superiore a 3.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/call-lightning'),
    ('calm-emotions', '2024', 'Calma le emozioni', 2, 'ammaliamento', array['bardo', 'chierico']::text[], 'Azione', '18 metri', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, 'cha', null, null, null, null, null, null, null, null, 'Ogni umanoide all’interno di una sfera del raggio di 6 metri con centro in un punto da te scelto entro il raggio deve superare un tiro salvezza di Carisma o subire uno dei seguenti effetti (scegli uno per ogni creatura):

La creatura è immune alle condizioni Incantato e Spaventato fino al termine dell’incantesimo. Se la creatura era già incantata o spaventata, tali condizioni vengono soppresse per tutta la durata dell’incantesimo.

La creatura diventa indifferente nei confronti delle creature di tua scelta verso cui è ostile. Questa indifferenza cessa se il bersaglio subisce danni o assiste al fatto che i propri alleati subiscano danni. Quando l’incantesimo termina, l’atteggiamento della creatura torna alla normalità.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/calm-emotions'),
    ('catnap', '2024', 'Pisolino', 3, 'ammaliamento', array['artefice', 'bardo', 'stregone', 'mago']::text[], 'Azione', '9 metri', '10 minuti', 'S, M', 'un pizzico di sabbia', false, false, false, null, null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura consenziente in più per ogni livello di slot incantesimo superiore a 3.', 'Fai un gesto rassicurante e fino a tre creature consenzienti di tua scelta che puoi vedere entro il raggio d''azione subiscono la condizione Incosciente per tutta la durata dell’incantesimo. L’incantesimo termina su un bersaglio se questo subisce danni o se un’altra creatura compie un’azione per risvegliarlo. Se un bersaglio presenta la condizione «Incosciente» causata da questo incantesimo per l’intera durata, ottiene i benefici derivanti dal completamento di un Riposo Breve e non può essere nuovamente influenzato da questo incantesimo finché non completa un Riposo Lungo.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura consenziente in più per ogni livello di slot incantesimo superiore a 3.', 'Arcana Unleashed', 'https://5e-spellbook.app/spells/catnap'),
    ('chain-lightning', '2024', 'Catena di fulmini', 6, 'invocazione', array['stregone', 'mago']::text[], 'Azione', '45 metri', 'Istantanea', 'V, S, M', 'tre spille d''argento', false, false, false, 'dex', null, '10d8', null, 'fulmine', null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Per ogni livello di slot incantesimo superiore a 6, un fulmine aggiuntivo balza dal primo bersaglio a un altro bersaglio.', 'Lanci un fulmine verso un bersaglio che puoi vedere entro il raggio d''azione. Tre fulmini balzano quindi da quel bersaglio verso un massimo di altri tre bersagli a tua scelta, ciascuno dei quali deve trovarsi entro 9 metri dal primo bersaglio. Un bersaglio può essere una creatura o un oggetto e può essere colpito solo da uno dei fulmini.

Ogni bersaglio effettua un tiro salvezza di Destrezza, subendo 10d8 danni da fulmine in caso di fallimento o metà dei danni in caso di successo.

Utilizzo di uno slot incantesimo di livello superiore. Per ogni livello di slot incantesimo superiore a 6, un fulmine aggiuntivo balza dal primo bersaglio a un altro bersaglio.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/chain-lightning'),
    ('charm-monster', '2024', 'Incantare un mostro', 4, 'ammaliamento', array['bardo', 'druido', 'stregone', 'warlock', 'mago']::text[], 'Azione', '9 metri', '1 ora', 'V, S', null, false, false, false, 'wis', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello di slot incantesimo superiore a 4.', 'Una creatura che puoi vedere entro il raggio d''azione effettua un tiro salvezza di Saggezza. Lo fa con Vantaggio se tu o i tuoi alleati la state combattendo. In caso di tiro di salvataggio fallito, il bersaglio subisce la condizione «Incantato» fino al termine dell’incantesimo o finché tu o i tuoi alleati non gli infliggete danni. La creatura «Incantata» è «Amichevole» nei tuoi confronti. Quando l’incantesimo termina, il bersaglio sa di essere stato «Incantato» da te.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello di slot incantesimo superiore a 4.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/charm-monster'),
    ('charm-person', '2024', 'Incantesimo "Incantare una persona"', 1, 'ammaliamento', array['bardo', 'druido', 'stregone', 'warlock', 'mago']::text[], 'Azione', '9 metri', '1 ora', 'V, S', null, false, false, false, 'wis', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Un umanoide che puoi vedere entro il raggio d''azione effettua un tiro salvezza di Saggezza. Lo fa con Vantaggio se tu o i tuoi alleati lo state combattendo. In caso di tiro di salvataggio fallito, il bersaglio subisce la condizione "Incantato" fino al termine dell’incantesimo o finché tu o i tuoi alleati non gli infliggete danni. La creatura "Incantata" è Amichevole nei tuoi confronti. Quando l’incantesimo termina, il bersaglio sa di essere stato Incantato da te.

Utilizzo di uno slot incantesimo di livello superiore. Puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/charm-person'),
    ('chill-touch', '2024', 'Tocco gelido', 0, 'necromanzia', array['stregone', 'warlock', 'mago']::text[], 'Azione', 'Contatto', 'Istantanea', 'V, S', null, false, false, true, null, 'melee', '1d10', null, 'necrotico', null, null, null, 'Potenziamento del trucchetto. Il danno aumenta di 1d10 quando raggiungi i livelli 5 (2d10), 11 (3d10) e 17 (4d10).', 'Canalizzando il gelo della tomba, effettua un attacco magico in mischia contro un bersaglio a portata. In caso di colpo andato a segno, il bersaglio subisce 1d10 danni necrotici e non può recuperare Punti Ferita fino alla fine del tuo prossimo turno.

Potenziamento del trucchetto. Il danno aumenta di 1d10 quando raggiungi i livelli 5 (2d10), 11 (3d10) e 17 (4d10).', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/chill-touch'),
    ('chromatic-orb', '2024', 'Sfera cromatica', 1, 'invocazione', array['stregone', 'mago']::text[], 'Azione', '27 metri', 'Istantanea', 'V, S, M', 'un diamante del valore di 50+ GP', false, false, true, null, 'ranged', null, null, null, '1d8', null, 2, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 1. La sfera può compiere un numero massimo di salti pari al livello dello slot utilizzato, e una creatura può essere presa di mira solo una volta per ogni lancio di questo incantesimo.', 'Lanci una sfera di energia contro un bersaglio entro la portata. Scegli Acido, Freddo, Fuoco, Fulmine, Veleno o Tuono come tipo di sfera da creare, quindi effettua un attacco magico a distanza contro il bersaglio. In caso di colpo, il bersaglio subisce 3d8 danni del tipo scelto.

Se ottieni lo stesso numero su due o più dadi d8, la sfera balza verso un bersaglio diverso a tua scelta entro 9 metri dal bersaglio. Effettua un tiro per colpire contro il nuovo bersaglio ed effettua un nuovo tiro per il danno. La sfera non può balzare di nuovo a meno che tu non lanci l’incantesimo utilizzando uno slot incantesimo di livello 2 o superiore.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 1. La sfera può compiere un numero massimo di salti pari al livello dello slot utilizzato, e una creatura può essere presa di mira solo una volta per ogni lancio di questo incantesimo.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/chromatic-orb'),
    ('circle-of-death', '2024', 'Cerchio della Morte', 6, 'necromanzia', array['stregone', 'warlock', 'mago']::text[], 'Azione', '45 metri', 'Istantanea', 'V, S, M', 'la polvere di una perla nera frantumata del valore di oltre 500 GP', false, false, false, 'con', null, '8d8', null, 'necrotico', '2d8', null, 7, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 2d8 per ogni livello dello slot incantesimo superiore a 6.', 'L''energia negativa si propaga in una sfera del raggio di 18 metri a partire da un punto a tua scelta entro il raggio d''azione. Ogni creatura presente in quell''area effettua un tiro salvezza di Costituzione, subendo 8d8 danni necrotici in caso di fallimento o metà dei danni in caso di successo.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 2d8 per ogni livello dello slot incantesimo superiore a 6.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/circle-of-death'),
    ('circle-of-power', '2024', 'Cerchio del Potere', 5, 'abiurazione', array['artefice', 'chierico', 'paladino', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 10 minuti', 'V', null, true, false, false, null, null, null, null, null, null, null, null, null, 'Per tutta la durata dell’effetto, da te si irradia un’aura in un’emanazione di 9 metri. All’interno dell’aura, tu e i tuoi alleati avete Vantaggio sui tiri salvezza contro incantesimi e altri effetti magici. Quando una creatura interessata effettua un tiro salvezza contro un incantesimo o un effetto magico che consente di subire solo metà dei danni in caso di successo, non subisce alcun danno se supera il tiro salvezza.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/circle-of-power'),
    ('clairvoyance', '2024', 'Chiaroveggenza', 3, 'divinazione', array['bardo', 'chierico', 'stregone', 'mago']::text[], '10 minuti', '1 miglio', 'Concentrazione, 10 minuti', 'V, S, M', 'un oggetto del valore di oltre 100 PO, a scelta tra un corno ingioiellato per l’udito o un occhio di vetro per la vista', true, false, false, null, null, null, null, null, null, null, null, null, 'Crei un sensore invisibile entro il raggio d’azione in un luogo a te familiare (un posto che hai già visitato o visto in precedenza) o in un luogo evidente ma a te sconosciuto (come dietro una porta, dietro un angolo o in un boschetto). Il sensore, intangibile e invulnerabile, rimane in posizione per tutta la durata dell’incantesimo.

Quando lanci l’incantesimo, scegli se usare la vista o l’udito. Puoi utilizzare il senso scelto attraverso il sensore come se ti trovassi nel suo spazio. Come azione bonus, puoi passare dalla vista all’udito e viceversa.

Una creatura che vede il sensore (come una creatura che beneficia di “Vedere l’invisibile” o “Vista vera”) vede una sfera luminosa delle dimensioni del tuo pugno.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/clairvoyance'),
    ('clone', '2024', 'Clone', 8, 'necromanzia', array['mago']::text[], '1 ora', 'Contatto', 'Istantanea', 'V, S, M', 'un diamante del valore di oltre 1.000 PO, che l’incantesimo consuma, e un recipiente sigillabile del valore di oltre 2.000 PO, abbastanza capiente da contenere la creatura da clonare', false, false, false, null, null, null, null, null, null, null, null, null, 'Tocchi una creatura o almeno 1 pollice cubo della sua carne. All’interno del contenitore utilizzato per lanciare l’incantesimo si forma un duplicato inerte di quella creatura, che completa la sua crescita dopo 120 giorni; sei tu a scegliere se il clone finito abbia la stessa età della creatura o sia più giovane. Il clone rimane inerte e perdura a tempo indeterminato fintanto che il suo contenitore non viene disturbato.

Se la creatura originale muore dopo che il clone ha completato la sua formazione, l’anima della creatura si trasferisce nel clone, purché l’anima sia libera e disposta a tornare. Il clone è fisicamente identico all’originale e possiede la stessa personalità, gli stessi ricordi e le stesse abilità, ma non l’equipaggiamento dell’originale. I resti originali della creatura, se presenti, diventano inerti e non possono essere riportati in vita, poiché l’anima della creatura si trova altrove.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/clone'),
    ('cloud-of-daggers', '2024', 'Nube di pugnali', 2, 'evocazione', array['bardo', 'stregone', 'warlock', 'mago']::text[], 'Azione', '18 metri', 'Concentrazione, 1 minuto', 'V, S, M', 'una scheggia di vetro', true, false, false, null, null, '4d4', null, 'tagliente', '2d4', null, 3, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 2d4 per ogni livello dello slot incantesimo superiore a 2.', 'Evoca dei pugnali rotanti in un cubo di 1,5 metri di lato con centro in un punto all’interno del raggio d’azione. Ogni creatura in quell’area subisce 4d4 danni da taglio. Una creatura subisce questo danno anche se entra nel cubo o termina il proprio turno al suo interno, oppure se il cubo si sposta nella sua casella. Una creatura subisce questo danno solo una volta per turno.

Nei tuoi turni successivi, puoi compiere un’azione magica per teletrasportare il cubo fino a 9 metri.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 2d4 per ogni livello dello slot incantesimo superiore a 2.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/cloud-of-daggers'),
    ('cloudkill', '2024', 'Cloudkill', 5, 'evocazione', array['stregone', 'mago']::text[], 'Azione', '36 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'con', null, '5d8', null, 'veleno', '1d8', null, 6, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 5.', 'Crei una Sfera di nebbia giallo-verde del raggio di 6 metri, centrata su un punto entro il raggio d’azione. La nebbia persiste per tutta la durata dell’incantesimo o finché un vento forte (come quello creato da Raffica di vento) non la disperde, ponendo fine all’incantesimo. La sua area è fortemente oscurata.

Ogni creatura all’interno della Sfera effettua un tiro salvezza di Costituzione, subendo 5d8 danni da veleno in caso di fallimento o metà dei danni in caso di successo. Una creatura deve effettuare questo tiro salvezza anche quando la Sfera si sposta nel suo spazio, quando entra nella Sfera o quando termina il proprio turno al suo interno. Una creatura effettua questo tiro salvezza solo una volta per turno.

All’inizio di ciascuno dei tuoi turni, la Sfera si allontana di 3 metri da te.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 5.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/cloudkill'),
    ('color-spray', '2024', 'Color Spray', 1, 'illusione', array['bardo', 'stregone', 'mago']::text[], 'Azione', 'Incantatore (cono di 4,5 metri)', 'Istantanea', 'V, S, M', 'un pizzico di sabbia colorata', false, false, false, 'con', null, null, null, null, null, null, null, null, 'Lanci una serie abbagliante di luci lampeggianti e colorate. Ogni creatura che si trova in un cono di 4,5 metri con centro in te deve superare un tiro salvezza di Costituzione, altrimenti subirà la condizione Accecato fino alla fine del tuo prossimo turno.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/color-spray'),
    ('command', '2024', 'Comando', 1, 'ammaliamento', array['bardo', 'chierico', 'paladino']::text[], 'Azione', '18 metri', 'Istantanea', 'V', null, false, false, false, 'wis', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. È possibile influenzare una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Pronunci un comando di una sola parola rivolto a una creatura che puoi vedere entro il raggio d''azione. Il bersaglio deve superare un tiro salvezza di Saggezza oppure eseguire il comando nel suo prossimo turno. Scegli il comando tra le seguenti opzioni:

Avvicinati. Il bersaglio si muove verso di te seguendo il percorso più breve e diretto, terminando il proprio turno se si avvicina a meno di 1,5 metri da te.

Lascia cadere. Il bersaglio lascia cadere qualsiasi cosa stia tenendo in mano e poi termina il proprio turno.

Fuggi. Il bersaglio trascorre il proprio turno allontanandosi da te nel modo più veloce possibile.

Strisciare. Il bersaglio si trova nella condizione Prono e poi termina il proprio turno.

Alt. Nel proprio turno, il bersaglio non si muove e non compie alcuna azione né azione bonus.

Utilizzo di uno slot incantesimo di livello superiore. È possibile influenzare una creatura aggiuntiva per ogni livello dello slot incantesimo superiore a 1.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/command'),
    ('commune', '2024', 'Comune', 5, 'divinazione', array['chierico']::text[], '1 minuto o Rituale', 'Personale', '1 minuto', 'V, S, M', 'incenso', false, true, false, null, null, null, null, null, null, null, null, null, 'Contatti una divinità o un suo rappresentante e poni fino a tre domande a cui è possibile rispondere con sì o no. Devi porre le tue domande prima che l’incantesimo finisca. Ricevi una risposta corretta per ogni domanda.

Gli esseri divini non sono necessariamente onniscienti, quindi potresti ricevere come risposta «non chiaro» se una domanda riguarda informazioni che esulano dalla conoscenza della divinità. Nel caso in cui una risposta di una sola parola possa essere fuorviante o contraria agli interessi della divinità, il DM potrebbe invece fornire una breve frase come risposta.

Se lanci l’incantesimo più di una volta prima di terminare un Riposo Lungo, c’è una probabilità cumulativa di 25 per ogni lancio successivo al primo di non ottenere alcuna risposta.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/commune'),
    ('commune-with-nature', '2024', 'Comunione con la natura', 5, 'divinazione', array['druido', 'ranger']::text[], '1 minuto o Rituale', 'Personale', '1 minuto', 'V, S', null, false, true, false, null, null, null, null, null, null, null, null, null, 'Entri in comunione con gli spiriti della natura e acquisisci conoscenza dell’area circostante. All’aperto, l’incantesimo ti fornisce informazioni sull’area entro un raggio di 3 miglia da te. Nelle caverne e in altri ambienti sotterranei naturali, il raggio è limitato a 90 metri. L’incantesimo non funziona dove la natura è stata sostituita da costruzioni, come nei castelli e negli insediamenti.

Scegli tre delle seguenti informazioni; apprendi tali informazioni nella misura in cui riguardano l’area dell’incantesimo:

Posizione degli insediamenti

Posizione dei portali verso altri piani dell’esistenza

Posizione di una creatura con Grado di Sfida 10+ (a scelta del DM) che sia un Celestiale, un Elementale, un Fata, un Demone o un Non-morto

Il tipo più diffuso di pianta, minerale o Bestia (scegli tu quale apprendere)

Posizione dei corsi d’acqua

Ad esempio, potresti determinare la posizione di un potente mostro nell’area, la posizione dei corsi d’acqua e quella di eventuali città.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/commune-with-nature'),
    ('compelled-duel', '2024', 'Duello forzato', 1, 'ammaliamento', array['paladino']::text[], 'Azione bonus', '9 metri', 'Concentrazione, 1 minuto', 'V', null, true, false, false, 'wis', null, null, null, null, null, null, null, null, 'Cerchi di costringere una creatura a duellare con te. Una creatura che puoi vedere entro il raggio d’azione effettua un tiro salvezza di Saggezza. In caso di fallimento, il bersaglio subisce Svantaggio sui tiri per colpire contro creature diverse da te e non può spostarsi volontariamente in uno spazio che disti più di 9 metri da te.

L’incantesimo termina se effettui un tiro per colpire contro una creatura diversa dal bersaglio, se lanci un incantesimo su un nemico diverso dal bersaglio, se un tuo alleato infligge danni al bersaglio o se concludi il tuo turno a più di 9 metri di distanza dal bersaglio.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/compelled-duel'),
    ('comprehend-languages', '2024', 'Comprensione delle lingue', 1, 'divinazione', array['bardo', 'stregone', 'warlock', 'mago']::text[], 'Azione o Rituale', 'Personale', '1 ora', 'V, S, M', 'un pizzico di fuliggine e sale', false, true, false, null, null, null, null, null, null, null, null, null, 'Per tutta la durata dell’incantesimo, comprendi il significato letterale di qualsiasi lingua che senti o vedi espressa con il linguaggio dei segni. Comprendi anche qualsiasi lingua scritta che vedi, ma devi toccare la superficie su cui sono scritte le parole. Ci vuole circa 1 minuto per leggere una pagina di testo. Questo incantesimo non decodifica simboli o messaggi segreti.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/comprehend-languages'),
    ('compulsion', '2024', 'Coercizione', 4, 'ammaliamento', array['bardo']::text[], 'Azione', '9 metri', 'Concentrazione, 1 minuto', 'V, S', null, true, false, false, 'wis', null, null, null, null, null, null, null, null, 'Ogni creatura a tua scelta che puoi vedere entro il raggio d’azione deve superare un tiro salvezza di Saggezza oppure subire la condizione Incantato fino al termine dell’incantesimo.

Per tutta la durata dell’incantesimo, puoi compiere un’azione bonus per indicare una direzione orizzontale rispetto a te. Ogni bersaglio incantato deve utilizzare quanto più movimento possibile per spostarsi in quella direzione nel suo prossimo turno, seguendo il percorso più sicuro. Dopo essersi spostato in questo modo, il bersaglio ripete il tiro di salvataggio e, in caso di successo, l’incantesimo su di lui termina.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/compulsion'),
    ('cone-of-cold', '2024', 'Cono di freddo', 5, 'invocazione', array['druido', 'stregone', 'mago']::text[], 'Azione', 'Incantatore (cono di 18 metri)', 'Istantanea', 'V, S, M', 'un piccolo cono di cristallo o di vetro', false, false, false, 'con', null, '8d8', null, 'freddo', '1d8', null, 6, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 5.', 'Scateni una raffica di aria gelida. Ogni creatura all’interno di un cono di 18 metri con centro in te effettua un tiro salvezza di Costituzione, subendo 8d8 danni da freddo in caso di fallimento o metà dei danni in caso di successo. Una creatura uccisa da questo incantesimo si trasforma in una statua di ghiaccio finché non si scioglie.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 5.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/cone-of-cold'),
    ('confusion', '2024', 'Confusione', 4, 'ammaliamento', array['bardo', 'druido', 'stregone', 'mago']::text[], 'Azione', '27 metri', 'Concentrazione, 1 minuto', 'V, S, M', 'tre gusci di noce', true, false, false, 'wis', null, null, null, null, null, null, null, 'Utilizzo di uno slot incantesimo di livello superiore. Il raggio della Sfera aumenta di 1,5 metri per ogni livello dello slot incantesimo superiore a 4.', 'Ogni creatura all’interno di una sfera del raggio di 3 metri con centro in un punto a tua scelta entro il raggio deve superare un tiro salvezza di Saggezza; in caso contrario, quel bersaglio non può compiere azioni bonus o reazioni e deve tirare 1d10 all’inizio di ciascuno dei propri turni per determinare il proprio comportamento per quel turno, consultando la tabella sottostante.

1d10

Comportamento per il turno

1

Il bersaglio non compie alcuna azione e utilizza tutto il suo movimento per spostarsi. Tira 1d4 per determinare la direzione: 1, nord; 2, est; 3, sud; o 4, ovest.

2-6

Il bersaglio non si muove né compie azioni.

7-8

Il bersaglio non si muove e compie l’azione Attacco per effettuare un attacco in mischia contro una creatura casuale a portata. Se non ce ne sono a portata, il bersaglio non compie alcuna azione.

9-10

Il bersaglio sceglie il proprio comportamento.

Alla fine di ciascuno dei propri turni, un bersaglio affetto ripete il tiro di salvataggio, ponendo fine all’incantesimo su se stesso in caso di successo.

Utilizzo di uno slot incantesimo di livello superiore. Il raggio della Sfera aumenta di 1,5 metri per ogni livello dello slot incantesimo superiore a 4.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/confusion'),
    ('conjure-animals', '2024', 'Evocazione di animali', 3, 'evocazione', array['druido', 'ranger']::text[], 'Azione', '18 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'dex', null, '3d10', null, 'tagliente', '1d10', null, 4, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d10 per ogni livello dello slot incantesimo superiore a 3.', 'Evoca spiriti della natura che appaiono come un branco di animali spettrali e intangibili di taglia Grande in uno spazio libero che puoi vedere entro il raggio d''azione. Il branco permane per tutta la durata dell''incantesimo e puoi scegliere la forma animale degli spiriti, come lupi, serpenti o uccelli.

Hai Vantaggio sui tiri salvezza di Forza mentre ti trovi entro 1,5 metri dal branco e, quando ti muovi nel tuo turno, puoi anche spostare il branco fino a 9 metri in uno spazio libero che puoi vedere.

Ogni volta che il branco si sposta entro 3 metri da una creatura che puoi vedere e ogni volta che una creatura che puoi vedere entra in uno spazio entro 3 metri dal branco o termina il proprio turno lì, puoi costringere quella creatura a effettuare un tiro salvezza di Destrezza. In caso di tiro di salvataggio fallito, la creatura subisce 3d10 danni da taglio. Una creatura effettua questo tiro di salvataggio solo una volta per turno.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d10 per ogni livello dello slot incantesimo superiore a 3.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-animals'),
    ('conjure-barrage', '2024', 'Conjure Barrage', 3, 'evocazione', array['ranger']::text[], 'Azione', 'Incantatore (cono di 18 metri)', 'Istantanea', 'V, S, M', 'un''arma da mischia o a distanza del valore di almeno 1 CP', false, false, false, 'dex', null, '5d8', null, 'forza', '1d8', null, 4, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 3.', 'Brandisci l’arma usata per lanciare l’incantesimo ed evochi armi spettrali simili (o munizioni adatte all’arma) che si lanciano in avanti per poi scomparire. Ogni creatura a tua scelta che puoi vedere all’interno di un cono di 18 metri effettua un tiro salvezza di Destrezza, subendo 5d8 danni da Forza in caso di fallimento o metà dei danni in caso di successo.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 3.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-barrage'),
    ('conjure-celestial', '2024', 'Evocare un Celestiale', 7, 'evocazione', array['chierico']::text[], 'Azione', '27 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'dex', null, '6d12', null, 'radioso', '1d12', null, 8, 'Utilizzo di uno slot incantesimo di livello superiore. La cura e il danno aumentano di 1d12 per ogni livello dello slot incantesimo superiore a 7.', 'Evoca uno spirito dai Piani Superiori, che si manifesta come una colonna di luce all’interno di un cilindro del raggio di 3 metri e alto 12 metri, con centro in un punto all’interno del raggio d’azione. Per ogni creatura che riesci a vedere all’interno del cilindro, scegli quale di queste luci la illumini:

Luce curativa. Il bersaglio recupera Punti Ferita pari a 4d12 più il tuo modificatore all’abilità di incantesimo.

Luce bruciante. Il bersaglio effettua un tiro salvezza di Destrezza, subendo 6d12 danni da Radiante in caso di fallimento o metà dei danni in caso di successo.

Fino al termine dell’incantesimo, una luce brillante riempie il cilindro e, quando ti muovi nel tuo turno, puoi anche spostare il cilindro fino a 9 metri.

Ogni volta che il Cilindro si sposta nello spazio di una creatura che puoi vedere e ogni volta che una creatura che puoi vedere entra nel Cilindro o termina il proprio turno al suo interno, puoi inondarla con una delle luci. Una creatura può essere influenzata da questo incantesimo solo una volta per turno.

Utilizzo di uno slot incantesimo di livello superiore. La cura e il danno aumentano di 1d12 per ogni livello dello slot incantesimo superiore a 7.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-celestial'),
    ('conjure-constructs', '2024', 'Evocare costrutti', 3, 'evocazione', array['mago']::text[], 'Azione', '18 metri', 'Concentrazione, 10 minuti', 'V, S, M', 'un ingranaggio di ottone', true, false, false, 'dex', null, '3d6', null, 'forza', '1d6', null, 4, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno e i Punti Ferita temporanei aumentano entrambi di 1d6 per ogni livello dello slot incantesimo superiore a 3.', 'Evoca un gruppo di spiriti intangibili e ordinati che appaiono come un gruppo di modron di taglia media o altri costrutti in uno spazio libero che puoi vedere entro il raggio d''azione. Gli spiriti permangono per tutta la durata dell’incantesimo. Quando lanci questo incantesimo e come azione magica nei turni successivi, puoi ordinare agli spiriti di prendere di mira una creatura o un oggetto che puoi vedere entro 1,5 metri dagli spiriti e creare uno dei seguenti effetti:

Forza meccanica. Il bersaglio effettua un tiro salvezza di Destrezza, subendo 3d6 danni da Forza in caso di fallimento o metà dei danni in caso di successo.

Barriera ordinata. Il bersaglio ottiene Punti Ferita temporanei pari a 1d6 più il tuo modificatore all’abilità di incantesimo.

Quando ti muovi nel tuo turno, puoi anche spostare gli spiriti fino a 9 metri in uno spazio libero che puoi vedere.

Utilizzo di uno slot incantesimo di livello superiore. Il danno e i Punti Ferita temporanei aumentano entrambi di 1d6 per ogni livello dello slot incantesimo superiore a 3.', 'Forgotten Realms: Heroes of Faerûn', 'https://5e-spellbook.app/spells/conjure-constructs'),
    ('conjure-elemental', '2024', 'Evocare un elementale', 5, 'evocazione', array['druido', 'mago']::text[], 'Azione', '18 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'dex', null, null, null, null, '1d8', null, 6, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 5.', 'Evoca uno spirito di taglia Grande e intangibile proveniente dai Piani Elementali, che appare in uno spazio libero entro il raggio d''azione. Scegli l''elemento dello spirito, che ne determina il tipo di danno: aria (Fulmine), terra (Tuono), fuoco (Fuoco) o acqua (Freddo). Lo spirito permane per tutta la durata dell''incantesimo.

Ogni volta che una creatura che puoi vedere entra nello spazio dello spirito o inizia il proprio turno entro 1,5 metri dallo spirito, puoi costringere quella creatura a effettuare un tiro salvezza di Destrezza, a meno che lo spirito non abbia già una creatura in stato di "Immobilizzato". In caso di tiro di salvataggio fallito, il bersaglio subisce 8d8 danni del tipo dello spirito e si trova nella condizione “Immobilizzato” fino al termine dell’incantesimo. All’inizio di ciascuno dei propri turni, il bersaglio “Immobilizzato” ripete il tiro di salvataggio. In caso di tiro di salvataggio fallito, il bersaglio subisce 4d8 danni del tipo dello spirito. In caso di tiro di salvataggio riuscito, il bersaglio non è "Restrained" dallo spirito.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 5.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-elemental'),
    ('conjure-fey', '2024', 'Conjure Fey', 6, 'evocazione', array['druido']::text[], 'Azione', '18 metri', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, null, null, null, null, null, '1d12', null, 7, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d12 per ogni livello dello slot incantesimo superiore a 6.', 'Evoca uno spirito di taglia media proveniente dal Feywild in uno spazio libero che puoi vedere entro il raggio d’azione. Lo spirito rimane per tutta la durata dell’incantesimo e assume l’aspetto di una creatura fatata a tua scelta. Quando lo spirito appare, puoi effettuare un attacco magico in mischia contro una creatura che si trovi entro 1,5 metri da esso. In caso di colpo andante, il bersaglio subisce danni psichici pari a 3d12 più il tuo modificatore di abilità di incantesimo e si trova nella condizione Spaventato fino all’inizio del tuo prossimo turno, con te e lo spirito come fonte della paura.

Come azione bonus nei tuoi turni successivi, puoi teletrasportare lo spirito in uno spazio libero che riesci a vedere entro 9 metri dallo spazio che ha lasciato ed effettuare l’attacco contro una creatura entro 1,5 metri da esso.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d12 per ogni livello dello slot incantesimo superiore a 6.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-fey'),
    ('conjure-minor-elementals', '2024', 'Evocare elementali minori', 4, 'evocazione', array['druido', 'mago']::text[], 'Azione', 'Personale', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, null, null, null, null, null, '1d8', null, 5, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 4.', 'Evoca spiriti dai Piani Elementali che aleggiano intorno a te in un''Emanazione di 4,5 metri per tutta la durata dell''incantesimo. Fino al termine dell''incantesimo, qualsiasi attacco che sferri infligge 2d8 danni aggiuntivi quando colpisci una creatura all''interno dell''Emanazione. Questo danno è di tipo Acido, Freddo, Fuoco o Fulmine (a tua scelta quando effettui l’attacco).

Inoltre, il terreno all’interno dell’Emanazione costituisce Terreno Difficile per i tuoi nemici.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 4.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-minor-elementals'),
    ('conjure-volley', '2024', 'Conjure Volley', 5, 'evocazione', array['ranger']::text[], 'Azione', '45 metri', 'Istantanea', 'V, S, M', 'un''arma da mischia o a distanza del valore di almeno 1 CP', false, false, false, 'dex', null, '8d8', null, 'forza', null, null, null, null, 'Brandisci l’arma usata per lanciare l’incantesimo e scegli un punto entro il raggio d’azione. Centinaia di armi spettrali simili (o munizioni adatte all’arma) piombano in una raffica per poi scomparire. Ogni creatura di tua scelta che puoi vedere all’interno di un cilindro del raggio di 12 metri e dell’altezza di 6 metri, con centro in quel punto, effettua un tiro salvezza di Destrezza. Una creatura subisce 8d8 danni da Forza in caso di tiro salvezza fallito o metà dei danni in caso di tiro salvezza riuscito.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-volley'),
    ('conjure-woodland-beings', '2024', 'Evocare creature dei boschi', 4, 'evocazione', array['druido', 'ranger']::text[], 'Azione', 'Personale', 'Concentrazione, 10 minuti', 'V, S', null, true, false, false, 'wis', null, '5d8', null, 'forza', '1d8', null, 5, 'Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 4.', 'Evoca spiriti della natura che svolazzano intorno a te in un''Emanazione di 3 metri per tutta la durata dell''incantesimo. Ogni volta che l''Emanazione entra nello spazio di una creatura che puoi vedere e ogni volta che una creatura che puoi vedere entra nell''Emanazione o termina il proprio turno al suo interno, puoi costringere quella creatura a effettuare un tiro salvezza di Saggezza. La creatura subisce 5d8 danni da Forza in caso di tiro di salvataggio fallito o metà dei danni in caso di tiro riuscito. Una creatura effettua questo tiro di salvataggio solo una volta per turno.

Inoltre, puoi eseguire l’azione Disimpegno come azione bonus per tutta la durata dell’incantesimo.

Utilizzo di uno slot incantesimo di livello superiore. Il danno aumenta di 1d8 per ogni livello dello slot incantesimo superiore a 4.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/conjure-woodland-beings'),
    ('contact-other-plane', '2024', 'Contatta l’altro piano', 5, 'divinazione', array['warlock', 'mago']::text[], '1 minuto o Rituale', 'Personale', '1 minuto', 'V', null, false, true, false, 'int', null, '6d6', null, 'psichico', null, null, null, null, 'Entri in contatto mentale con un semidio, lo spirito di un saggio morto da tempo o qualche altra entità sapiente proveniente da un altro piano. Entrare in contatto con questa intelligenza ultraterrena può farti impazzire. Quando lanci questo incantesimo, effettua un tiro salvezza di Intelligenza con CD 15. Se il tiro salvezza ha esito positivo, puoi porre all’entità fino a cinque domande. Devi porre le tue domande prima che l’incantesimo finisca. Il DM risponde a ciascuna domanda con una sola parola, come «sì», «no», «forse», «mai», «irrilevante» o «non chiaro» (se l’entità non conosce la risposta alla domanda). Se una risposta di una sola parola fosse fuorviante, il DM potrebbe invece fornire una breve frase come risposta.

In caso di tiro di salvataggio fallito, subisci 6d6 danni psichici e subisci la condizione Incapacitato fino al termine di un Riposo Lungo. Un incantesimo di Restauro Maggiore lanciato su di te pone fine a questo effetto.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/contact-other-plane'),
    ('contagion', '2024', 'Contagio', 5, 'necromanzia', array['chierico', 'druido']::text[], 'Azione', 'Contatto', '7 giorni', 'V, S', null, false, false, false, 'con', null, '11d8', null, 'necrotico', null, null, null, null, 'Il tuo tocco infligge un contagio magico. Il bersaglio deve superare un tiro salvezza di Costituzione oppure subire 11d8 danni necrotici e subire la condizione Avvelenato. Inoltre, scegli un''abilità quando lanci l''incantesimo. Finché è Avvelenato, il bersaglio ha Svantaggio sui tiri salvezza effettuati con l''abilità scelta.

Il bersaglio deve ripetere il tiro salvezza alla fine di ciascuno dei propri turni finché non ottiene tre successi o tre fallimenti. Se il bersaglio supera tre di questi tiri salvezza, l’incantesimo termina su di lui. Se il bersaglio fallisce tre di questi tiri salvezza, l’incantesimo dura 7 giorni su di lui.

Ogni volta che il bersaglio Avvelenato subisce un effetto che farebbe cessare la condizione Avvelenato, deve superare un tiro salvezza di Costituzione; in caso contrario, la condizione Avvelenato non cessa su di lui.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/contagion'),
    ('contingency', '2024', 'Contingenza', 6, 'abiurazione', array['mago']::text[], '10 minuti', 'Personale', '10 giorni', 'V, S, M', 'una statuetta di te stesso tempestata di gemme del valore di oltre 1.500 PO', false, false, false, null, null, null, null, null, null, null, null, null, 'Scegli un incantesimo di livello 5 o inferiore che puoi lanciare, che abbia un tempo di lancio pari a un''azione e che possa avere te come bersaglio. Lanci quell''incantesimo — chiamato incantesimo contingente — come parte del lancio di Contingenza, consumando slot incantesimo per entrambi, ma l''incantesimo contingente non entra in vigore. Entra invece in vigore quando si verifica un determinato evento scatenante. Descrivi tale evento scatenante quando lanci i due incantesimi. Ad esempio, un incantesimo Contingenza lanciato insieme a Respirazione acquatica potrebbe stabilire che Respirazione acquatica entri in vigore quando sei sommerso dall’acqua o da un liquido simile.

L’incantesimo contingente entra in vigore immediatamente dopo che l’evento scatenante si verifica per la prima volta, indipendentemente dalla tua volontà, dopodiché Contingenza termina.

L’incantesimo contingente ha effetto solo su di te, anche se normalmente può avere come bersaglio altre persone. Puoi usare un solo incantesimo di Contingenza alla volta. Se lanci nuovamente questo incantesimo, l’effetto di un altro incantesimo di Contingenza su di te termina. Inoltre, Contingenza termina su di te se il suo componente materiale non è più in tuo possesso.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/contingency'),
    ('continual-flame', '2024', 'Fiamma Continua', 2, 'invocazione', array['artefice', 'chierico', 'druido', 'mago']::text[], 'Azione', 'Contatto', 'Finché non viene dissolto', 'V, S, M', 'polvere di rubino del valore di oltre 50 PO, che l’incantesimo consuma', false, false, false, null, null, null, null, null, null, null, null, null, 'Da un oggetto che tocchi scaturisce una fiamma. L’effetto genera una Luce Intensa in un raggio di 6 metri e una Luce Debole per altri 6 metri. Sembra una fiamma normale, ma non produce calore e non consuma combustibile. La fiamma può essere coperta o nascosta, ma non può essere soffocata né spenta.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/continual-flame'),
    ('control-water', '2024', 'Controllo dell’acqua', 4, 'trasmutazione', array['chierico', 'druido', 'mago']::text[], 'Azione', '90 metri', 'Concentrazione, 10 minuti', 'V, S, M', 'una miscela di acqua e polvere', true, false, false, 'str', null, '2d8', null, 'contundente', null, null, null, null, 'Fino al termine dell’incantesimo, controlli l’acqua all’interno di un’area a tua scelta che sia un cubo con lato massimo di 30 metri, utilizzando uno dei seguenti effetti. Come azione magica nei tuoi turni successivi, puoi ripetere lo stesso effetto o sceglierne uno diverso.

Inondazione. Fai salire il livello di tutta l’acqua stagnante nell’area fino a un massimo di 6 metri. Se scegli un’area all’interno di un grande specchio d’acqua, crei invece un’onda alta 6 metri che si propaga da un lato all’altro dell’area per poi infrangersi. Qualsiasi veicolo di taglia Enorme o inferiore che si trovi sul percorso dell’onda viene trascinato con essa dall’altra parte. Qualsiasi veicolo di taglia Enorme o inferiore colpito dall’onda ha una probabilità del 25% di capovolgersi.

Il livello dell’acqua rimane elevato fino al termine dell’incantesimo o finché non scegli un effetto diverso. Se questo effetto ha generato un’onda, l’onda si ripete all’inizio del tuo prossimo turno finché dura l’effetto inondazione.

Dividi l’acqua. Dividi l’acqua nell’area e crei un fossato. Il fossato si estende per tutta l’area dell’incantesimo e l’acqua separata forma una parete su entrambi i lati. Il fossato rimane fino al termine dell’incantesimo o finché non scegli un effetto diverso. L’acqua riempie poi lentamente il fossato nel corso del round successivo, fino a ripristinare il normale livello dell’acqua.

Reindirizza il flusso. Fai sì che l’acqua che scorre nell’area si muova nella direzione da te scelta, anche se ciò comporta che l’acqua debba scorrere sopra ostacoli, risalire pareti o seguire altre direzioni improbabili. L’acqua nell’area si muove secondo le tue indicazioni, ma una volta che esce dall’area dell’incantesimo, riprende il suo flusso in base al terreno. L’acqua continua a muoversi nella direzione da te scelta finché l’incantesimo non termina o non scegli un effetto diverso.

Vortice. Fai sì che si formi un vortice al centro dell’area, che deve essere di almeno 15 metri per lato e profonda 7,5 metri. Il vortice dura finché non scegli un effetto diverso o l’incantesimo non termina. Il vortice è largo 1,5 metri alla base, fino a 15 metri in cima, ed è alto 7,5 metri. Qualsiasi creatura che si trovi in acqua e entro 7,5 metri dal vortice viene trascinata di 3 metri verso di esso. Quando una creatura entra nel vortice per la prima volta in un turno o termina il proprio turno al suo interno, effettua un tiro salvezza di Forza. In caso di fallimento, la creatura subisce 2d8 danni da contusione. In caso di tiro di salvataggio riuscito, la creatura subisce metà del danno. Una creatura può allontanarsi a nuoto dal vortice solo se prima compie un’azione per allontanarsi e supera un tiro di Forza (Atletica) contro la tua CD di salvataggio dell’incantesimo.', 'Manuale del Giocatore (2024)', 'https://5e-spellbook.app/spells/control-water'),
    ('control-weather', '2024', 'Controllare il tempo', 8, 'trasmutazione', array['chierico', 'druido', 'mago']::text[], '10 minuti', 'Se stesso (raggio di 5 miglia)', 'Concentrazione, 8 ore', 'V, S, M', 'bruciare incenso', true, false, false, null, null, null, null, null, null, null, null, null, 'Per tutta la durata dell’incantesimo, assumi il controllo delle condizioni meteorologiche entro un raggio di 5 miglia da te. Devi trovarti all’aperto per lanciare questo incantesimo, che termina anticipatamente se entri in un luogo chiuso.

Quando lanci l’incantesimo, modifichi le condizioni meteorologiche attuali, che sono determinate dal DM. Puoi modificare le precipitazioni, la temperatura e il vento. Ci vogliono 1d4 × 10 minuti affinché le nuove condizioni entrino in vigore. Una volta che ciò avviene, puoi modificare nuovamente le condizioni. Al termine dell’incantesimo, il tempo torna gradualmente alla normalità.

Quando modifichi le condizioni meteorologiche, individua una condizione attuale nelle tabelle seguenti e modifica il suo livello di un punto, in aumento o in diminuzione. Quando modifichi il vento, puoi cambiarne la direzione.

Precipitazioni

